@startuml

class Product {
  + Name : string
  + Description : string
  + NetPrice : float
}

class Manufacturer {
  + Name : string
  + Country : string
}

class Country {
  + Name : string
  + VATRate : float
  + Currency : string
  + ConversionRateToEuro : float
}

class Representative {
  + FirstName : string
  + LastName : string
  + SocialSecurityNumber : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Customer {
  + Name : string
  + Address : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Order {
  + OrderID : string
  + Quantity : int
  + OrderDate : date
  + DesiredDeliveryDate : date
}

Product "*" -- "1" Manufacturer
Product "*" -- "*" Country
Representative "1" -- "1" Country
Customer "*" -- "*" Country
Representative "1" -- "*" Order
Order "*" -- "1" Product
Order "*" -- "1" Customer

@enduml

